<template>
 <els-dynamic-designer-view :init-root-form="true" :append-data-types="dataTypes" :append-component-types="componentData">
     <template #left="{customData}">
         <div style="width:100%" class="flex">
             <div>
                 <el-tabs tab-position="left" >
                     <el-tab-pane v-for="item in componentTypeData" :label="item.TypeName"></el-tab-pane>
                 </el-tabs>
             </div>
             <div>
                 <draggable tag="ul" :list="customData" item-key="keyID"
                            :group="{ name: 'dragGroup', pull: 'clone', put: false }" :clone="handleClone"
                            :sort="false">
                     <template #item="{ element, index }">
                         <li class="container-widget-item" :key="index">
                             <els-image :url="element.componentPreview"></els-image>
                         </li>
                     </template>
                 </draggable>
                </div>
     
         </div>
     </template>
 </els-dynamic-designer-view>
</template>

